/* ---------- set limit ---------- */
.lim{max-width:420px;padding:16px}
.lim-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}
.lim-head .t{font-size:15px;font-weight:600}
.lim-sub{margin-top:2px;font-size:12.5px;color:var(--muted)}
.lim-bar{position:relative;height:26px;margin-top:18px;background:var(--chip);overflow:hidden}
.lim-bar i{position:absolute;left:0;top:0;bottom:0;width:0;background:repeating-linear-gradient(135deg,rgba(255,255,255,.22) 0 4px,transparent 4px 9px),var(--lc,#3ecf8e);transition:width .9s var(--ease),background-color .4s ease}
.lim-bar.over i{animation:lim-pulse 1.4s ease-in-out infinite}
@keyframes lim-pulse{50%{filter:brightness(1.12)}}
.lim-nums{display:flex;justify-content:space-between;margin-top:8px;font-size:13px}
.lim-nums span:first-child{font-weight:600;color:var(--text)}
.lim-nums span:last-child{color:var(--muted)}
.lim-state{margin-top:10px;font-size:12.5px;color:var(--text-dim)}
.lim-ed{margin-top:14px;padding-top:14px;border-top:1px solid var(--line)}
.lim-row{display:flex;align-items:center;gap:12px}
.lim-cur{font-size:18px;font-weight:600;color:var(--muted)}
.lim-row input[type="text"],#lim-in{width:110px;height:38px;padding:0 10px;background:var(--panel);border:1px solid var(--icon-line);outline:0;font:inherit;font-size:16px;font-weight:600;color:var(--text)}
#lim-in:focus{border-color:var(--accent)}
#lim-rng{flex:1;accent-color:var(--accent)}
.lim-pre{display:flex;gap:6px;margin-top:10px}
.lim-pre button{padding:5px 10px;border:1px solid var(--line);font-size:12.5px;font-weight:500;color:var(--text-dim);transition:border-color .2s,color .2s}
.lim-pre button:hover,.lim-pre button.on{border-color:var(--accent);color:var(--text)}
.lim-acts{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}
[data-style="soft"] .lim,[data-style="soft"] .cv{border-radius:20px}
[data-style="soft"] .lim-bar,[data-style="soft"] .lim-bar i{border-radius:10px}
[data-style="soft"] #lim-in{border-radius:10px;border-width:1.5px}
[data-style="soft"] .lim-pre button{border-radius:999px;border-width:1.5px}

/* ---------- set limit ---------- */
{
  const fill = $('#lim-fill'), bar = $('#lim-bar'), fold = $('#lim-fold'), inp = $('#lim-in'), rng = $('#lim-rng');
  const used = 8600; let limit = 10000, draft = limit;
  const money = n => '$' + Math.round(n).toLocaleString('en-US');
  function paint(first){
    const pct = Math.min(100, used / limit * 100), over = used > limit;
    bar.style.setProperty('--lc', over ? '#ff5a5f' : pct >= 80 ? '#f2a705' : 'var(--lc-ok)'); bar.classList.toggle('over', over);
    fill.style.width = pct + '%'; $('#lim-max').textContent = money(limit);
    swapText($('#lim-state'), over ? `Over the limit by ${money(used - limit)}, new payments are paused` : pct >= 80 ? `${money(limit - used)} left, ${Math.round(pct)}% of the limit used` : `${money(limit - used)} left this month`);
    if (first) countTo($('#lim-used'), used, { dur:900 });
  }
  $('#lim-pre').innerHTML = [5000, 8000, 10000, 15000].map(v => `<button data-v="${v}">${money(v)}</button>`).join('');
  const setDraft = v => { draft = v; inp.value = Math.round(v).toLocaleString('en-US'); rng.value = v; $$('#lim-pre button').forEach(b => b.classList.toggle('on', +b.dataset.v === v)); };
  $('#lim-edit').addEventListener('click', () => { const open = !fold.classList.contains('open'); morph($('#lim'), () => fold.classList.toggle('open', open)); setDraft(limit); Sound.play(open ? 'open' : 'close'); if (open) setTimeout(() => inp.focus(), 300); });
  rng.addEventListener('input', () => { setDraft(+rng.value); Sound.play('stream'); });
  inp.addEventListener('input', () => { const v = +inp.value.replace(/\D/g, ''); if (v) { draft = v; rng.value = v; } });
  $('#lim-pre').addEventListener('click', e => { const b = e.target.closest('button'); if (b){ setDraft(+b.dataset.v); Sound.play('tick'); } });
  $('#lim-cancel').addEventListener('click', () => { morph($('#lim'), () => fold.classList.remove('open')); Sound.play('close'); });
  $('#lim-save').addEventListener('click', () => { limit = Math.max(500, draft); morph($('#lim'), () => fold.classList.remove('open')); paint(); Sound.play('done'); showToast('Limit set to ' + money(limit)); });
  inp.addEventListener('keydown', e => { if (e.key === 'Enter') $('#lim-save').click(); });
  whenSeen($('#c74'), () => paint(true));
}
